
  /* ===== SUITES: the declared key column (KEY-1) ===== */

  /* A section's key column used to be recoverable only by RENDERING the section and
   * reading its first pipe-table header cell back out of the markdown. That worked for
   * three adapters that all happen to emit pipe tables, and returned nothing at all for
   * any provider that does not — a trap laid for the next host rather than for this one.
   *
   * It is declared now. These tests pin the declared labels to the ones the scrape
   * produced, because the extraction may not change a generated byte. */
  T.suite('KEY-1 an adapter declares its key column rather than having it scraped', function (s) {
    function adapter(id) { ensureAndroid(); return App.registry.getDataset('android-adb', id); }
    var IDS = ['android.packages', 'android.tactical', 'android.custom'];

    s.test('every dataset adapter declares one', function () {
      IDS.forEach(function (id) {
        var k = adapter(id).keyColumn;
        T.assert(k && typeof k.get === 'function', id + ': no keyColumn.get');
        T.assert(typeof k.label === 'string' && k.label.length, id + ': no keyColumn.label');
      });
    });

    s.test('the declared label is exactly what the scrape used to recover', function () {
      T.assertEqual(adapter('android.packages').keyColumn.label, 'Package');
      T.assertEqual(adapter('android.tactical').keyColumn.label, 'Path');
      T.assertEqual(adapter('android.custom').keyColumn.label, 'Action Name');
    });

    s.test('the getter still reads the value the table printed', function () {
      T.assertEqual(adapter('android.packages').keyColumn.get({ key: 'com.a' }), 'com.a');
      // Tactical strips the policy prefix for display; that is the getter's job.
      var t = adapter('android.tactical').keyColumn;
      T.assertEqual(typeof t.get({ key: 'x' }), 'string');
    });

    s.test('sectionColumns reports the declared label without rendering a probe', function () {
      var p = readyProject();
      var cols = App.generate.sectionColumns(p, { kind: 'dataset', dsId: 'android.packages' }, {});
      T.assertEqual(cols.fixed[0].id, '_key');
      T.assertEqual(cols.fixed[0].label, 'Package');
    });
  });
